static int wait_tgphy_cmd_ready(struct r8152 *tp)
{
	int i, ret;

	for (i = 0; i < 10; i++) {
		u32 ocp_data;

		ret = ocp_read_word(tp, MCU_TYPE_USB, USB_TGPHY_CMD, &ocp_data);
		if (ret < 0)
			break;
		else if (!(ocp_data & TGPHY_CMD_BUSY))
			break;
		usleep_range(1000, 2000);
	}

	if (i == 10)
		ret = -ETIMEDOUT;

	return ret;
}
